import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BUS5y9ZA.js";const b=JSON.parse('{"title":"올바름 인력관리시스템 운영 매뉴얼","description":"","frontmatter":{},"headers":[],"relativePath":"operations-manual.md","filePath":"operations-manual.md"}'),o={name:"operations-manual.md"};function d(i,t,n,h,c,s){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="올바름-인력관리시스템-운영-매뉴얼" tabindex="-1">올바름 인력관리시스템 운영 매뉴얼 <a class="header-anchor" href="#올바름-인력관리시스템-운영-매뉴얼" aria-label="Permalink to &quot;올바름 인력관리시스템 운영 매뉴얼&quot;">​</a></h1><h2 id="_1-운영-역할" tabindex="-1">1. 운영 역할 <a class="header-anchor" href="#_1-운영-역할" aria-label="Permalink to &quot;1. 운영 역할&quot;">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>주요 업무</th></tr></thead><tbody><tr><td>관리자</td><td>직원·근무지·배정·교육·점검·리포트·계정 관리</td></tr><tr><td>시스템 운영 담당자</td><td>배포, 환경변수, DB, 로그, 장애 대응, 백업 관리</td></tr><tr><td>현장 근무자</td><td>출퇴근, 교육 이수, 점검, 특이사항 보고</td></tr></tbody></table><h2 id="_2-일상-운영" tabindex="-1">2. 일상 운영 <a class="header-anchor" href="#_2-일상-운영" aria-label="Permalink to &quot;2. 일상 운영&quot;">​</a></h2><h3 id="_2-1-직원과-배정" tabindex="-1">2.1 직원과 배정 <a class="header-anchor" href="#_2-1-직원과-배정" aria-label="Permalink to &quot;2.1 직원과 배정&quot;">​</a></h3><ol><li>직원 등록 시 이름, 연락처, 직무를 확인한다.</li><li>퇴직자는 삭제보다 퇴직 상태 처리를 우선한다.</li><li>근무지 주소와 GPS 좌표, 출근 인정 반경을 확인한다.</li><li>직원별 배정 시작일과 종료일이 겹치지 않게 등록한다.</li></ol><h4 id="_2-1-1-배정등록-저장-시-근무일·휴무일·출퇴근-예정시각-기준" tabindex="-1">2.1.1 배정등록 저장 시 근무일·휴무일·출퇴근 예정시각 기준 <a class="header-anchor" href="#_2-1-1-배정등록-저장-시-근무일·휴무일·출퇴근-예정시각-기준" aria-label="Permalink to &quot;2.1.1 배정등록 저장 시 근무일·휴무일·출퇴근 예정시각 기준&quot;">​</a></h4><p>배정등록을 저장하면 선택한 직원의 근무형태와 출퇴근 시간을 기준으로 배정기간의 날짜별 예정시각이 생성된다. 배정등록 화면에 표시되는 출근·퇴근 시간은 직원 정보에 설정된 값을 기본으로 하며, 저장 시 배정의 기준 시간으로 함께 보관한다. 시간이 별도로 전달되지 않는 경우에는 직원 정보의 출퇴근 시간을 사용한다. 날짜별 예정시각은 한국 시간 기준으로 관리한다.</p><table tabindex="0"><thead><tr><th>근무형태</th><th>배정 저장 시 적용 기준</th></tr></thead><tbody><tr><td>일반근무(0)</td><td>배정기간의 모든 날짜에 출근 예정시각과 퇴근 예정시각을 생성한다. 토·일 및 공휴일을 자동 휴무로 처리하지 않는다.</td></tr><tr><td>24시간근무(1)</td><td>배정 시작일을 기준으로 하루씩 교대한다. 시작일에서 0일, 2일, 4일처럼 짝수 번째 날짜에는 출근 예정시각을, 1일, 3일, 5일처럼 홀수 번째 날짜에는 퇴근 예정시각을 생성한다.</td></tr><tr><td>야간근무(2)</td><td>토요일·일요일 또는 공휴일 관리에서 <code>선택=Y</code>인 날짜를 자동 휴무일로 등록한다. 휴무일에는 출근 예정시각을 만들지 않으며, 전날 출근 예정이 있으면 해당 날짜에는 퇴근 예정시각만 만든다. 전날 출근 예정이 없으면 출퇴근 예정시각을 만들지 않는다.</td></tr></tbody></table><p>야간근무의 휴무일 판단은 공휴일 API에서 내려온 날짜 자체가 아니라 공휴일 관리 목록에서 <code>선택</code> 값이 <code>Y</code>인 날짜를 기준으로 한다. 공휴일이지만 <code>N</code>으로 저장된 날짜는 자동 휴무 대상이 아니다. 수동 휴무일 지정은 배정 수정 화면의 휴무일 캘린더에서 근무기간 안의 날짜를 선택해 저장하며, 저장된 날짜에는 근무자의 출근을 허용하지 않는다.</p><p>출퇴근 예정시각은 <code>work_assignment_daily_attendance</code>에 날짜별로 저장되며, 야간근무의 휴무일 처리를 포함해 이후 출결 등록과 근태 판정의 기준으로 사용한다. 배정 저장 후 배정 수정 화면의 달력에서 날짜별 출근·퇴근 예정시각과 휴무일 표시를 확인한다.</p><h3 id="_2-2-근태" tabindex="-1">2.2 근태 <a class="header-anchor" href="#_2-2-근태" aria-label="Permalink to &quot;2.2 근태&quot;">​</a></h3><ul><li>대시보드에서 당일 출근 현황과 미출근 상태를 확인한다.</li><li>근태 리포트의 직원명·연도 조건으로 이력을 조회한다.</li><li>GPS 오류 신고 시 기기 위치 권한, 당일 배정, 근무지 좌표와 반경을 순서대로 점검한다.</li></ul><h4 id="_2-2-1-근태관리의-지각-판정-기준" tabindex="-1">2.2.1 근태관리의 <code>지각</code> 판정 기준 <a class="header-anchor" href="#_2-2-1-근태관리의-지각-판정-기준" aria-label="Permalink to &quot;2.2.1 근태관리의 `지각` 판정 기준&quot;">​</a></h4><p>근태관리 목록은 다음 조건을 모두 만족하는 배정의 예정 출근시각과 실제 출근일시를 비교한다.</p><ol><li>같은 직원이다.</li><li>같은 근무지이다.</li><li>같은 근무일이다.</li><li>해당 날짜의 배정별 예정 출근시각(<code>intime</code>)이 존재한다.</li></ol><p>실제 출근일시가 예정 출근시각보다 늦으면 목록의 상태에 <code>지각</code>을 표시한다. 예정시각과 같거나 이르면 <code>지각</code>으로 표시하지 않는다. 예정 출근시각이 없는 휴무일, 배정과 일치하지 않는 근태기록, 출근일시가 없는 기록은 지각으로 판정하지 않는다. 근태기록을 수정한 경우 다음 목록 조회에서 수정된 출근일시를 기준으로 다시 판정하며, 엑셀 다운로드에도 동일한 상태가 포함된다.</p><h3 id="_2-3-안전교육" tabindex="-1">2.3 안전교육 <a class="header-anchor" href="#_2-3-안전교육" aria-label="Permalink to &quot;2.3 안전교육&quot;">​</a></h3><ul><li>교육 제목과 재생 가능한 영상 링크를 등록한다.</li><li>직원별 전체·이수·미이수 건수를 확인한다.</li><li>미이수 알림 발송 전 대상 인원과 구독 상태를 확인한다.</li><li>자동 발송 실패 시 실행 이력의 오류 사유를 확인하고 수동 발송을 검토한다.</li></ul><h3 id="_2-4-점검과-특이사항" tabindex="-1">2.4 점검과 특이사항 <a class="header-anchor" href="#_2-4-점검과-특이사항" aria-label="Permalink to &quot;2.4 점검과 특이사항&quot;">​</a></h3><ul><li>점검 현장을 근무지에 연결하고 QR 정보를 생성한다.</li><li>점검 이력은 최신 순으로 확인하고 필요 시 근무지로 필터링한다.</li><li>특이사항 보고의 내용, 사진, 위치와 Naver mail 전달 상태를 확인한다.</li><li>보고 삭제 시 연결 사진도 함께 삭제되므로 대상 내용을 다시 확인한다.</li></ul><h2 id="_3-계정-및-설정-관리" tabindex="-1">3. 계정 및 설정 관리 <a class="header-anchor" href="#_3-계정-및-설정-관리" aria-label="Permalink to &quot;3. 계정 및 설정 관리&quot;">​</a></h2><ul><li>관리자 계정은 업무상 필요한 사용자만 등록한다.</li><li>담당자 변경 또는 퇴사 시 관리자 계정을 즉시 정리한다.</li><li>시스템 설정 코드는 운영 기능에서 참조하므로 의미를 확인한 후 수정한다.</li><li>비밀번호와 서비스 키는 문서나 메신저에 평문으로 공유하지 않는다.</li></ul><h3 id="_3-1-네이버-메일-발신-계정-등록-및-변경" tabindex="-1">3.1 네이버 메일 발신 계정 등록 및 변경 <a class="header-anchor" href="#_3-1-네이버-메일-발신-계정-등록-및-변경" aria-label="Permalink to &quot;3.1 네이버 메일 발신 계정 등록 및 변경&quot;">​</a></h3><p>특이사항 보고에 사용할 네이버 발신 계정을 새로 등록하거나 교체할 때 다음 순서로 진행한다. 현재 구현에서는 코드 수정 없이 네이버 계정 설정과 Vercel 환경변수 변경으로 적용할 수 있다.</p><h4 id="_1-네이버-2단계-인증과-애플리케이션-비밀번호-준비" tabindex="-1">1. 네이버 2단계 인증과 애플리케이션 비밀번호 준비 <a class="header-anchor" href="#_1-네이버-2단계-인증과-애플리케이션-비밀번호-준비" aria-label="Permalink to &quot;1. 네이버 2단계 인증과 애플리케이션 비밀번호 준비&quot;">​</a></h4><ol><li>발신용 네이버 계정으로 로그인한다.</li><li>네이버 계정의 보안설정에서 2단계 인증을 활성화한다.</li><li>애플리케이션 비밀번호를 발급한다. SMTP 인증에는 일반 로그인 비밀번호가 아닌 이 비밀번호를 사용한다.</li></ol><p>네이버는 2025년 6월 24일부터 외부 메일 연동에 2단계 인증과 애플리케이션 비밀번호를 요구한다. 자세한 절차는 <a href="https://help.naver.com/service/30029/contents/24347?lang=ko&amp;osType=COMMONOS" target="_blank" rel="noreferrer">네이버 공식 FAQ</a>를 참고한다.</p><h4 id="_2-네이버-메일에서-smtp-사용-허용" tabindex="-1">2. 네이버 메일에서 SMTP 사용 허용 <a class="header-anchor" href="#_2-네이버-메일에서-smtp-사용-허용" aria-label="Permalink to &quot;2. 네이버 메일에서 SMTP 사용 허용&quot;">​</a></h4><ol><li>PC 네이버 메일의 <strong>환경설정 → POP3/IMAP 설정 → POP3/SMTP 설정</strong>으로 이동한다.</li><li><strong>POP3/SMTP 사용</strong>을 <strong>사용함</strong>으로 변경하고 저장한다.</li><li>SMTP 서버는 <code>smtp.naver.com</code>, 포트는 <code>465</code>, 보안 연결은 SSL을 사용한다.</li></ol><p><a href="https://help.naver.com/service/30029/contents/21341?lang=ko&amp;osType=PC" target="_blank" rel="noreferrer">네이버 SMTP 설정 안내</a></p><h4 id="_3-vercel-환경변수-등록" tabindex="-1">3. Vercel 환경변수 등록 <a class="header-anchor" href="#_3-vercel-환경변수-등록" aria-label="Permalink to &quot;3. Vercel 환경변수 등록&quot;">​</a></h4><p>Vercel의 해당 프로젝트에서 <strong>Settings → Environment Variables</strong>로 이동하여 아래 값을 등록하거나 변경한다. 운영 사이트에는 <strong>Production</strong> 환경으로 적용한다.</p><table tabindex="0"><thead><tr><th>환경변수</th><th>입력할 값</th><th>비고</th></tr></thead><tbody><tr><td><code>NAVER_SMTP_USER</code></td><td>새 발신 계정 이메일, 예: <code>example@naver.com</code></td><td>필수</td></tr><tr><td><code>NAVER_SMTP_PASSWORD</code></td><td>네이버에서 발급한 애플리케이션 비밀번호</td><td>일반 로그인 비밀번호 사용 불가</td></tr><tr><td><code>NAVER_SMTP_PORT</code></td><td><code>465</code></td><td>필수. 현재 코드는 이 포트에서 SSL 사용</td></tr><tr><td><code>NAVER_SMTP_FROM</code></td><td>새 발신 계정 이메일</td><td>생략하면 <code>NAVER_SMTP_USER</code> 사용. 계정 교체 시 기존 주소가 남지 않도록 확인</td></tr></tbody></table><p>애플리케이션 비밀번호는 환경변수로만 저장하며 GitHub 코드, 프로젝트 문서, 메신저에 기록하지 않는다. SMTP 서버 주소는 코드에서 <code>smtp.naver.com</code>으로 지정되어 있으므로 별도 환경변수를 추가할 필요가 없다.</p><h4 id="_4-보고서-수신-주소-설정" tabindex="-1">4. 보고서 수신 주소 설정 <a class="header-anchor" href="#_4-보고서-수신-주소-설정" aria-label="Permalink to &quot;4. 보고서 수신 주소 설정&quot;">​</a></h4><ol><li><a href="https://ollbareun.vercel.app/manager/system/configs" target="_blank" rel="noreferrer">관리자 시스템설정</a>으로 이동한다.</li><li>시스템코드 **<code>manager_email</code>**의 내용을 보고서를 받을 이메일 주소로 설정한다.</li></ol><p>발신 계정은 Vercel 환경변수에서, 수신 주소는 시스템설정의 <code>manager_email</code>에서 관리한다. 수신 주소만 변경한다면 네이버 발신 계정을 새로 등록하거나 SMTP 환경변수를 변경할 필요가 없다.</p><h4 id="_5-재배포-및-수신-확인" tabindex="-1">5. 재배포 및 수신 확인 <a class="header-anchor" href="#_5-재배포-및-수신-확인" aria-label="Permalink to &quot;5. 재배포 및 수신 확인&quot;">​</a></h4><ol><li>환경변수 저장 후 Vercel에서 <strong>Redeploy</strong>를 실행한다. 환경변수 변경은 새 배포부터 적용된다. <a href="https://vercel.com/docs/environment-variables" target="_blank" rel="noreferrer">Vercel 환경변수 안내</a></li><li>배포 완료 후 근무자의 <strong>특이사항</strong> 화면에서 테스트 보고를 작성한다. 관리자에게 테스트임을 알 수 있도록 내용에 <strong>메일 설정 테스트</strong>를 명시한다.</li><li><strong>보고하기</strong>를 누르고 완료 안내에서 NAVER 이메일 발송 결과를 확인한다.</li><li><code>manager_email</code>에 설정한 수신 계정의 받은편지함과 스팸함에서 실제 수신 여부를 확인한다.</li></ol><p>현재 <strong>보고하기</strong>는 보고서를 한 번 저장한 뒤 관리자 푸시알림 전송을 시도하고, 이어서 NAVER 이메일을 전송한다. 따라서 테스트 보고도 관리자 푸시알림이 함께 발송된다. 푸시 전송 실패 시에도 이메일 발송은 시도하며, 완료 안내에서 두 결과를 각각 확인할 수 있다.</p><h4 id="발송-실패-시-확인-사항" tabindex="-1">발송 실패 시 확인 사항 <a class="header-anchor" href="#발송-실패-시-확인-사항" aria-label="Permalink to &quot;발송 실패 시 확인 사항&quot;">​</a></h4><ul><li>네이버 계정의 2단계 인증 및 POP3/SMTP 사용 설정을 확인한다.</li><li><code>NAVER_SMTP_PASSWORD</code>에 유효한 애플리케이션 비밀번호가 입력되어 있는지 확인한다.</li><li><code>NAVER_SMTP_USER</code>와 <code>NAVER_SMTP_FROM</code>이 새 발신 계정으로 설정되어 있는지 확인한다.</li><li><code>NAVER_SMTP_PORT</code>가 <code>465</code>인지, 환경변수가 Production에 적용되어 있는지 확인한다.</li><li>환경변수 변경 후 재배포했는지 확인한다.</li><li><code>manager_email</code>의 수신 주소, 스팸함 및 Vercel 오류 로그를 확인한다.</li></ul><h3 id="_3-2-공휴일-정보-api-신청-및-설정" tabindex="-1">3.2 공휴일 정보 API 신청 및 설정 <a class="header-anchor" href="#_3-2-공휴일-정보-api-신청-및-설정" aria-label="Permalink to &quot;3.2 공휴일 정보 API 신청 및 설정&quot;">​</a></h3><ol><li><a href="https://www.data.go.kr/data/15012690/openapi.do" target="_blank" rel="noreferrer">공공데이터포털 한국천문연구원 특일 정보</a>에 접속하고 로그인합니다.</li><li><strong>활용신청</strong>을 선택하여 사용 목적과 필요한 신청 항목을 입력합니다. 신청한 서비스의 승인 상태와 이용 가능한 호출 한도를 확인합니다.</li><li>마이페이지의 OpenAPI 활용 내역에서 해당 서비스의 **일반 인증키(Decoding)**를 확인합니다. 인증키는 공개 문서나 GitHub에 올리지 않습니다.</li><li>Vercel 프로젝트의 Settings → Environment Variables에 서버 환경변수 <strong>DATA_GO_KR_SERVICE_KEY</strong>를 만들고 인증키를 값으로 등록합니다. 운영 서비스는 Production 환경에 적용합니다. 변수 이름에 NEXT_PUBLIC_을 붙이지 않습니다.</li><li>환경변수를 저장한 뒤 재배포(Redeploy)합니다. 로컬 개발 시에는 같은 변수를 커밋하지 않는 .env.local에 설정합니다.</li><li>관리자 → 직원관리 → <strong>공휴일관리</strong>에서 연도를 입력하고 <strong>공휴일가져오기</strong>를 누릅니다. 확인창에서 해당 연도를 확인하고 승인합니다.</li></ol><p>공휴일 조회 기능(getRestDeInfo)으로 해당 연도의 자료를 받아 공휴일 여부가 Y인 날짜만 저장합니다. 신규 날짜의 선택값은 Y이며, 이미 존재하는 날짜는 수정하지 않고 건너뜁니다. 다시 가져와도 기존 이름과 선택값은 유지됩니다. 결과 메시지에서 등록 건수와 건너뛴 건수를 확인합니다.</p><p>목록의 <strong>선택</strong> 체크박스를 변경하면 Y/N 값이 즉시 저장됩니다. <strong>휴일추가</strong>에서는 날짜를 입력하여 선택값 Y로 직접 등록할 수 있습니다. 중복 날짜는 등록되지 않습니다. 공휴일 선택값은 야간근무(2)의 배정 저장 시 일정 생성에 자동 반영됩니다. 선택값이 <code>Y</code>인 공휴일은 주말과 같은 휴무일 기준으로 처리됩니다. 일반근무(0)와 24시간근무(1)은 공휴일·주말을 자동 휴무로 처리하지 않으므로 필요한 경우 배정 수정 화면에서 휴무일을 수동 지정합니다.</p><p>인증키가 없으면 설정 안내가 표시됩니다. 가져오기 실패 시 활용승인 여부, 인증키, 요청 한도, 공공데이터포털 서비스 상태를 확인합니다. 임시공휴일 등 변경 사항이 발표되면 해당 연도를 다시 가져오고, 기존 자료의 변경이 필요한 경우에는 선택값을 직접 조정합니다. API 등록 정보와 제공 범위는 공공데이터포털의 최신 안내를 기준으로 확인합니다.</p><h2 id="_4-정기-점검" tabindex="-1">4. 정기 점검 <a class="header-anchor" href="#_4-정기-점검" aria-label="Permalink to &quot;4. 정기 점검&quot;">​</a></h2><table tabindex="0"><thead><tr><th>주기</th><th>점검 항목</th></tr></thead><tbody><tr><td>매일</td><td>관리자 로그인, 주요 화면, 오류 로그, 교육 알림 결과</td></tr><tr><td>매주</td><td>미처리 특이사항, 실패 메일·푸시, 비정상 근태 데이터</td></tr><tr><td>매월</td><td>관리자 계정, DB 용량, Storage 용량, 외부 서비스 사용량</td></tr><tr><td>분기</td><td>키 교체 필요성, 백업 복구 훈련, 브라우저·모바일 호환성</td></tr></tbody></table><h2 id="_5-장애-대응" tabindex="-1">5. 장애 대응 <a class="header-anchor" href="#_5-장애-대응" aria-label="Permalink to &quot;5. 장애 대응&quot;">​</a></h2><ol><li>발생 시각, 사용자, 화면, 재현 절차와 오류 문구를 확보한다.</li><li>전체 장애인지 특정 사용자·기기·근무지 문제인지 구분한다.</li><li>Vercel 로그, Supabase 상태와 외부 서비스 상태를 확인한다.</li><li>데이터 손상 가능성이 있으면 쓰기 작업을 제한하고 백업을 확보한다.</li><li>복구 후 원인, 영향, 조치, 재발 방지 내용을 기록한다.</li></ol><h2 id="_6-주요-문제-해결" tabindex="-1">6. 주요 문제 해결 <a class="header-anchor" href="#_6-주요-문제-해결" aria-label="Permalink to &quot;6. 주요 문제 해결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>증상</th><th>확인 순서</th></tr></thead><tbody><tr><td>관리자 로그인 실패</td><td>Supabase Auth, 관리자 등록, 콜백 URL, 쿠키</td></tr><tr><td>근무자 로그인 실패</td><td>이름·연락처, 전화번호 정규화, 퇴직 상태</td></tr><tr><td>출근 불가</td><td>당일 배정, 위치 권한, GPS 정확도, 인정 반경</td></tr><tr><td>교육 영상 재생 불가</td><td>영상 URL, 외부 공개 상태, 브라우저 네트워크</td></tr><tr><td>푸시 미수신</td><td>알림 권한, 구독 정보, VAPID 키, 실행 이력</td></tr><tr><td>메일 전송 실패</td><td>Naver SMTP 계정·비밀번호·포트, 수신 주소</td></tr><tr><td>지도 표시 실패</td><td>Kakao 키, 허용 도메인, 주소·좌표 값</td></tr></tbody></table><h2 id="_7-백업과-개인정보" tabindex="-1">7. 백업과 개인정보 <a class="header-anchor" href="#_7-백업과-개인정보" aria-label="Permalink to &quot;7. 백업과 개인정보&quot;">​</a></h2><ul><li>Supabase 백업 정책과 복구 가능 기간을 정기적으로 확인한다.</li><li>복구 훈련 시 별도 환경에서 데이터 정합성을 검증한다.</li><li>연락처, 위치, 사진은 업무 목적 범위에서만 조회·보관한다.</li><li>불필요해진 개인정보와 접근 권한은 내부 보존 정책에 따라 정리한다.</li></ul><h2 id="_8-문의-접수-기준" tabindex="-1">8. 문의 접수 기준 <a class="header-anchor" href="#_8-문의-접수-기준" aria-label="Permalink to &quot;8. 문의 접수 기준&quot;">​</a></h2><ul><li>접수 내용에는 사용자 구분, 발생 시각, 화면명, 기기·브라우저, 재현 절차를 포함한다.</li><li>개인정보와 인증정보가 포함된 화면은 필요한 부분만 마스킹하여 전달한다.</li><li>긴급도는 서비스 중단, 데이터 손실·보안, 주요 기능 장애, 일반 문의 순으로 분류한다.</li></ul>',58)])])}const u=e(o,[["render",d]]);export{b as __pageData,u as default};
